import { CohereClient, Cohere } from "cohere-ai";

const client = new CohereClient({ token: "YOUR_TOKEN", clientName: "YOUR_CLIENT_NAME" });
await client.chat({
    message: "Can you give me a global market overview of solar panels?",
    chatHistory: [{
            role: "TOOL"
        }, {
            role: "TOOL"
        }],
    promptTruncation: Cohere.ChatRequestPromptTruncation.Off,
    temperature: 0.3
});

codeSamples.code:
package main

import (
	"context"
	"log"

	cohere "github.com/cohere-ai/cohere-go/v2"
	client "github.com/cohere-ai/cohere-go/v2/client"
)

func main() {
	co := client.NewClient()

	resp, err := co.Chat(
		context.TODO(),
		&cohere.ChatRequest{
			ChatHistory: []*cohere.Message{
				{
					Role: "USER",
					User: &cohere.ChatMessage{
						Message: "Who discovered gravity?",
					},
				},
				{
					Role: "CHATBOT",
					Chatbot: &cohere.ChatMessage{
						Message: "The man who is widely credited with discovering gravity is Sir Isaac Newton",
					},
				}},
			Message: "What year was he born?",
			Connectors: []*cohere.ChatConnector{
				{Id: "web-search"},
			},
		},
	)

	if err != nil {
		log.Fatal(err)
	}

	log.Printf("%+v", resp)
}

const { CohereClient } = require('cohere-ai');

const cohere = new CohereClient({});

(async () => {
  const response = await cohere.chat({
    chatHistory: [
      { role: 'USER', message: 'Who discovered gravity?' },
      {
        role: 'CHATBOT',
        message: 'The man who is widely credited with discovering gravity is Sir Isaac Newton',
      },
    ],
    message: 'What year was he born?',
    // perform web search before answering the question. You can also use your own custom connector.
    connectors: [{ id: 'web-search' }],
  });

  console.log(response);
})();

